with

sq_stg_supplies2 as (

    select
        cast(stg_supplies2.supply_cost as double) as supply_cost,
        cast(stg_supplies2.product_id as varchar) as product_id
    from {{ ref('stg_supplies') }} as stg_supplies2

),

agg_supplies_by_product2 as (

    select
        sq_stg_supplies2.product_id as product_id,
        sum(sq_stg_supplies2.supply_cost) as supply_cost_per_product
    from sq_stg_supplies2
    group by sq_stg_supplies2.product_id

),

sq_stg_order_items1 as (

    select
        cast(stg_order_items1.order_id as varchar) as order_id,
        cast(stg_order_items1.product_id as varchar) as product_id
    from {{ ref('stg_order_items') }} as stg_order_items1

),

sq_stg_products2 as (

    select
        cast(stg_products2.product_id as varchar) as product_id,
        cast(stg_products2.product_price as double) as product_price,
        cast(stg_products2.is_food_item as double) as is_food_item,
        cast(stg_products2.is_drink_item as double) as is_drink_item
    from {{ ref('stg_products') }} as stg_products2

),

jnr_items_products as (

    select
        master.order_id as order_id,
        detail.product_id as product_id,
        detail.product_price as product_price,
        detail.is_food_item as is_food_item,
        detail.is_drink_item as is_drink_item
    from sq_stg_products2 as detail
    inner join sq_stg_order_items1 as master
        on master.product_id = detail.product_id

),

jnr_items_supplies as (

    select
        master.order_id as order_id,
        master.product_price as product_price,
        master.is_food_item as is_food_item,
        master.is_drink_item as is_drink_item,
        detail.supply_cost_per_product as supply_cost_per_product
    from agg_supplies_by_product2 as detail
    left join jnr_items_products as master
        on master.product_id = detail.product_id

),

agg_items_by_order as (

    select
        jnr_items_supplies.order_id as order_id,
        sum(jnr_items_supplies.product_price) as order_items_subtotal,
        sum(case when (jnr_items_supplies.supply_cost_per_product is null) then 0 else jnr_items_supplies.supply_cost_per_product end) as order_cost,
        max(jnr_items_supplies.is_food_item) as has_food_items,
        max(jnr_items_supplies.is_drink_item) as has_drink_items
    from jnr_items_supplies
    group by jnr_items_supplies.order_id

),

sq_stg_orders1 as (

    select
        cast(stg_orders1.order_id as varchar) as order_id,
        cast(stg_orders1.customer_id as varchar) as customer_id,
        cast(stg_orders1.location_id as varchar) as location_id,
        cast(stg_orders1.ordered_at_day as timestamp) as ordered_at_day,
        cast(stg_orders1.subtotal_cents as double) as subtotal_cents,
        cast(stg_orders1.tax_paid_cents as double) as tax_paid_cents,
        cast(stg_orders1.order_total_cents as double) as order_total_cents
    from {{ ref('stg_orders') }} as stg_orders1

),

jnr_orders_items_agg as (

    select
        detail.order_id as order_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.subtotal_cents as subtotal_cents,
        master.tax_paid_cents as tax_paid_cents,
        master.order_total_cents as order_total_cents,
        detail.order_items_subtotal as order_items_subtotal,
        detail.order_cost as order_cost,
        detail.has_food_items as has_food_items,
        detail.has_drink_items as has_drink_items
    from agg_items_by_order as detail
    left join sq_stg_orders1 as master
        on master.order_id = detail.order_id

),

exp_orders_calc as (

    select
        jnr_orders_items_agg.order_id as order_id,
        jnr_orders_items_agg.customer_id as customer_id,
        jnr_orders_items_agg.location_id as location_id,
        jnr_orders_items_agg.ordered_at_day as ordered_at_day,
        jnr_orders_items_agg.subtotal_cents / 100 as subtotal_recal,
        jnr_orders_items_agg.tax_paid_cents / 100 as tax_paid_recal,
        jnr_orders_items_agg.order_total_cents / 100 as order_total_recal,
        case when (jnr_orders_items_agg.order_items_subtotal is null) then 0 else jnr_orders_items_agg.order_items_subtotal end as order_items_subtotal_cl,
        case when (jnr_orders_items_agg.order_cost is null) then 0 else jnr_orders_items_agg.order_cost end as order_cost_cl,
        case when (jnr_orders_items_agg.has_food_items is null) then 0 else jnr_orders_items_agg.has_food_items end as has_food_items_cl,
        case when (jnr_orders_items_agg.has_drink_items is null) then 0 else jnr_orders_items_agg.has_drink_items end as has_drink_items_cl
    from jnr_orders_items_agg

),

exp_customer_order_num as (

    select
        exp_orders_calc.order_id as order_id,
        exp_orders_calc.customer_id as customer_id,
        exp_orders_calc.location_id as location_id,
        exp_orders_calc.ordered_at_day as ordered_at_day,
        exp_orders_calc.subtotal_recal as subtotal,
        exp_orders_calc.tax_paid_recal as tax_paid,
        exp_orders_calc.order_total_recal as order_total,
        exp_orders_calc.order_items_subtotal_cl as order_items_subtotal,
        exp_orders_calc.order_cost_cl as order_cost,
        exp_orders_calc.has_food_items_cl as has_food_items,
        exp_orders_calc.has_drink_items_cl as has_drink_items
    from exp_orders_calc

)

select
    cast(exp_customer_order_num.order_id as varchar) as order_id,
    cast(exp_customer_order_num.customer_id as varchar) as customer_id,
    cast(exp_customer_order_num.location_id as varchar) as location_id,
    cast(exp_customer_order_num.ordered_at_day as timestamp) as ordered_at_day,
    cast(exp_customer_order_num.subtotal as decimal(12,2)) as subtotal,
    cast(exp_customer_order_num.tax_paid as decimal(12,2)) as tax_paid,
    cast(exp_customer_order_num.order_total as decimal(12,2)) as order_total,
    cast(exp_customer_order_num.order_items_subtotal as decimal(12,2)) as order_items_subtotal,
    cast(exp_customer_order_num.order_cost as decimal(12,2)) as order_cost,
    cast(exp_customer_order_num.has_food_items as decimal(1,0)) as has_food_items,
    cast(exp_customer_order_num.has_drink_items as decimal(1,0)) as has_drink_items
from exp_customer_order_num
